        "content": "import { describe, expect, test } from \"bun:test\";\nimport { spawn } from \"child_process\";\nimport { readFileSync } from \"fs\";\nimport { dirname, join } from \"path\";\nimport { fileURLToPath } from \"url\";\n\nconst __dirname = dirname(fileURLToPath(import.meta.url));\n\n/**\n * Run the validate-json script with given input.\n */\nasync function runValidator(input: string): Promise<{ code: number; stdout: string; stderr: string }> {\n  return new Promise((resolve, reject) => {\n    const child = spawn(\"bun\", [\"run\", join(__dirname, \"validate-json.ts\")], {\n      stdio: [\"pipe\", \"pipe\", \"pipe\"]\n    });\n\n    let stdout = \"\";\n    let stderr = \"\";\n\n    if (input !== \"\") {\n      child.stdin.write(input);\n    }\n    child.stdin.end();\n\n    child.stdout.on(\"data\", (data) => {\n      stdout += data.toString();\n    });\n\n    child.stderr.on(\"data\", (data) => {\n      stderr += data.toString();\n    });\n\n    child.on(\"close\", (code) => {\n      resolve({ code: code ?? -1, stdout, stderr });\n    });\n\n    child.on(\"error\", reject);\n  });\n}\n\ndescribe(\"validate-json\", () => {\n  test(\"validates correct JSON object\", async () => {\n    const result = await runValidator('{\"name\": \"Alice\", \"age\": 30}');\n    expect(result.stdout.trim()).toBe(\"✓ Valid JSON\");\n    expect(result.code).toBe(0);\n  });\n\n  test(\"validates JSON array\", async () => {\n    const result = await runValidator('[1, 2, 3, 4, 5]');\n    expect(result.stdout.trim()).toBe(\"✓ Valid JSON\");\n    expect(result.code).toBe(0);\n  });\n\n  test(\"validates JSON string\", async () => {\n    const result = await runValidator('\"hello world\"');\n    expect(result.stdout.trim()).toBe(\"✓ Valid JSON\");\n    expect(result.code).toBe(0);\n  });\n\n  test(\"validates JSON number\", async () => {\n    const result = await runValidator('42');\n    expect(result.stdout.trim()).toBe(\"✓ Valid JSON\");\n    expect(result.code).toBe(0);\n  });\n\n  test(\"validates JSON boolean\", async () => {\n    const result = await runValidator('true');\n    expect(result.stdout.trim()).toBe(\"✓ Valid JSON\");\n    expect(result.code).toBe(0);\n  });\n\n  test(\"validates JSON null\", async () => {\n    const result = await runValidator('null');\n    expect(result.stdout.trim()).toBe(\"✓ Valid JSON\");\n    expect(result.code).toBe(0);\n  });\n\n  test(\"validates nested JSON\", async () => {\n    const result = await runValidator('{\"user\": {\"name\": \"Alice\", \"groups\": [\"admin\", \"user\"]}}');\n    expect(result.stdout.trim()).toBe(\"✓ Valid JSON\");\n    expect(result.code).toBe(0);\n  });\n\n  test(\"rejects missing closing brace\", async () => {\n    const result = await runValidator('{\"name\": \"Alice\"');\n    expect(result.stderr.trim()).toMatch(/✗ Invalid JSON:/);\n    expect(result.code).toBe(1);\n  });\n\n  test(\"rejects trailing comma in object\", async () => {\n    const result = await runValidator('{\"name\": \"Alice\",}');\n    expect(result.stderr.trim()).toMatch(/✗ Invalid JSON:/);\n    expect(result.code).toBe(1);\n  });\n\n  test(\"rejects missing quotes around property name\", async () => {\n    const result = await runValidator('{name: \"Alice\"}');\n    expect(result.stderr.trim()).toMatch(/✗ Invalid JSON:/);\n    expect(result.code).toBe(1);\n  });\n\n  test(\"rejects single quotes instead of double quotes\", async () => {\n    const result = await runValidator(\"{'name': 'Alice'}\");\n    expect(result.stderr.trim()).toMatch(/✗ Invalid JSON:/);\n    expect(result.code).toBe(1);\n  });\n\n  test(\"rejects trailing comma in array\", async () => {\n    const result = await runValidator('[1, 2, 3,]');\n    expect(result.stderr.trim()).toMatch(/✗ Invalid JSON:/);\n    expect(result.code).toBe(1);\n  });\n\n  test(\"rejects missing closing bracket in array\", async () => {\n    const result = await runValidator('[1, 2, 3');\n    expect(result.stderr.trim()).toMatch(/✗ Invalid JSON:/);\n    expect(result.code).toBe(1);\n  });\n\n  test(\"rejects undefined\", async () => {\n    const result = await runValidator('undefined');\n    expect(result.stderr.trim()).toMatch(/✗ Invalid JSON:/);\n    expect(result.code).toBe(1);\n  });\n\n  test(\"handles whitespace-only input\", async () => {\n    const result = await runValidator('   \\n\\t  ');\n    expect(result.stderr.trim()).toBe(\"Error: No input provided\");\n    expect(result.code).toBe(2);\n  });\n\n  test(\"handles empty input\", async () => {\n    const result = await runValidator('');\n    expect(result.stderr.trim()).toBe(\"Error: No input provided\");\n    expect(result.code).toBe(2);\n  });\n\n  test(\"handles whitespace around valid JSON\", async () => {\n    const result = await runValidator('\\n  {\"name\": \"Alice\"}  \\n');\n    expect(result.stdout.trim()).toBe(\"✓ Valid JSON\");\n    expect(result.code).toBe(0);\n  });\n});",
