export interface ValidationError {
  path: string;
  message: string;
  value?: unknown;
}

export interface ValidationResult {
  valid: boolean;
  errors?: ValidationError[];
  parseTime: number;
  validationTime: number;
}

export interface SchemaPattern {
  type: "string" | "number" | "boolean" | "object" | "array" | "null";
  required?: string[];
  properties?: Record<string, SchemaPattern>;
  items?: SchemaPattern;
  pattern?: RegExp;
  minimum?: number;
  maximum?: number;
}

const PARSE_ERROR_REGEX = /position (\d+)/;

function parseErrorPath(message: string): string {
  const match = message.match(PARSE_ERROR_REGEX);
  return match ? `at position ${match[1]}` : "at unknown position";
}

export function validateJson(
  input: string,
  schema?: SchemaPattern
): ValidationResult {
  const startTime = performance.now();

  let parsed: unknown;
  const parseStart = performance.now();

  try {
    parsed = JSON.parse(input);
  } catch (e) {
    const parseTime = performance.now() - parseStart;
    const error = e as Error;
    return {
      valid: false,
      errors: [
        {
          path: parseErrorPath(error.message),
          message: error.message.replace(/^JSON.parse: /, ""),
        },
      ],
      parseTime,
      validationTime: 0,
    };
  }

  const parseTime = performance.now() - parseStart;

  if (!schema) {
    return {
      valid: true,
      parseTime,
      validationTime: 0,
    };
  }

  const validateStart = performance.now();
  const errors: ValidationError[] = [];

  function validatePath(value: unknown, schemaNode: SchemaPattern, path: string): void {
    if (schemaNode.type === "string") {
      if (typeof value !== "string") {
        errors.push({ path, message: `Expected string, got ${typeof value}`, value });
        return;
      }
      if (schemaNode.pattern && !schemaNode.pattern.test(value)) {
        errors.push({ path, message: `String does not match required pattern`, value });
      }
    } else if (schemaNode.type === "number") {
      if (typeof value !== "number") {
        errors.push({ path, message: `Expected number, got ${typeof value}`, value });
        return;
      }
      if (schemaNode.minimum !== undefined && value < schemaNode.minimum) {
        errors.push({ path, message: `Number must be >= ${schemaNode.minimum}`, value });
      }
      if (schemaNode.maximum !== undefined && value > schemaNode.maximum) {
        errors.push({ path, message: `Number must be <= ${schemaNode.maximum}`, value });
      }
    } else if (schemaNode.type === "boolean") {
      if (typeof value !== "boolean") {
        errors.push({ path, message: `Expected boolean, got ${typeof value}`, value });
      }
    } else if (schemaNode.type === "null") {
      if (value !== null) {
        errors.push({ path, message: `Expected null, got ${typeof value}`, value });
      }
    } else if (schemaNode.type === "array") {
      if (!Array.isArray(value)) {
        errors.push({ path, message: `Expected array, got ${typeof value}`, value });
        return;
      }
      if (schemaNode.items) {
        for (let i = 0; i < value.length; i++) {
          validatePath(value[i], schemaNode.items, `${path}[${i}]`);
        }
      }
    } else if (schemaNode.type === "object") {
      if (typeof value !== "object" || value === null) {
        errors.push({ path, message: `Expected object, got ${typeof value}`, value });
        return;
      }
      const obj = value as Record<string, unknown>;

      for (const key of schemaNode.required ?? []) {
        if (!(key in obj)) {
          errors.push({ path: `${path}.${key}`, message: `Required property missing` });
        }
      }

      for (const [key, propSchema] of Object.entries(schemaNode.properties ?? {})) {
        if (key in obj) {
          validatePath(obj[key], propSchema, `${path}.${key}`);
        }
      }
    }
  }

  validatePath(parsed, schema, "root");

  const validationTime = performance.now() - validateStart;

  return {
    valid: errors.length === 0,
    errors: errors.length > 0 ? errors : undefined,
    parseTime,
    validationTime,
  };
}

#!/usr/bin/env bun
import { validateJson, type SchemaPattern } from "../src/json-validator";

const args = process.argv.slice(2);

function showUsage(): void {
  console.error(`
Usage: bun run validate-json <json-file> [schema-file]
   or: cat data.json | bun run validate-json [schema-file]

Arguments:
  json-file    Path to JSON file to validate (or read from stdin)
  schema-file  Optional path to JSON schema file for validation

Options:
  --help, -h   Show this help message

Exit codes:
  0            Valid JSON
  1            Invalid JSON or validation errors
  2            Usage error or file not found
`);
}

function parseSchema(schemaText: string): SchemaPattern | undefined {
  try {
    return JSON.parse(schemaText) as SchemaPattern;
  } catch {
    return undefined;
  }
}

async function main(): Promise<void> {
  if (args.includes("--help") || args.includes("-h")) {
    showUsage();
    process.exit(0);
  }

  const jsonPath = args[0];
  const schemaPath = args[1];

  const hasStdin = !process.stdin.isTTY;

  let jsonContent: string;
  let schemaContent: string | undefined;

  if (jsonPath && !jsonPath.startsWith("-")) {
    try {
      jsonContent = await Bun.file(jsonPath).text();
    } catch {
      console.error(`Error: Cannot read file: ${jsonPath}`);
      process.exit(2);
    }
  } else if (hasStdin) {
    jsonContent = await new Response(process.stdin).text();
  } else {
    showUsage();
    process.exit(2);
  }

  if (schemaPath) {
    try {
      schemaContent = await Bun.file(schemaPath).text();
    } catch {
      console.error(`Error: Cannot read schema file: ${schemaPath}`);
      process.exit(2);
    }
  }

  const schema = schemaContent ? parseSchema(schemaContent) : undefined;

  const result = validateJson(jsonContent, schema);

  console.log(`Parse time: ${result.parseTime.toFixed(3)}ms`);
  console.log(`Validation time: ${result.validationTime.toFixed(3)}ms`);
  console.log(`Total time: ${(result.parseTime + result.validationTime).toFixed(3)}ms`);

  if (result.valid) {
    console.log("\n✓ JSON is valid");
    if (schema) {
      console.log("✓ Schema validation passed");
    }
    process.exit(0);
  }

  console.log("\n✗ Validation failed:");
  for (const error of result.errors ?? []) {
    console.log(`  ${error.path}: ${error.message}`);
  }

  process.exit(1);
}

main().catch((err) => {
  console.error(err);
  process.exit(2);
});

import { describe, test, expect } from "bun:test";
import { validateJson, type SchemaPattern } from "./json-validator";

describe("validateJson - syntax validation", () => {
  test("validates valid JSON object", () => {
    const result = validateJson('{"name": "test", "value": 123}');
    expect(result.valid).toBe(true);
    expect(result.errors).toBeUndefined();
    expect(result.parseTime).toBeGreaterThanOrEqual(0);
  });

  test("validates valid JSON array", () => {
    const result = validateJson('[1, 2, 3, "four"]');
    expect(result.valid).toBe(true);
    expect(result.errors).toBeUndefined();
  });

  test("validates valid nested JSON", () => {
    const result = validateJson(`
      {
        "user": {
          "name": "John",
          "age": 30,
          "tags": ["admin", "user"]
        }
      }
    `);
    expect(result.valid).toBe(true);
    expect(result.errors).toBeUndefined();
  });

  test("detects missing closing bracket", () => {
    const result = validateJson('{"name": "test"');
    expect(result.valid).toBe(false);
    expect(result.errors).toBeDefined();
    expect(result.errors?.[0].message).toContain("Expected");
  });

  test("detects trailing comma", () => {
    const result = validateJson('{"name": "test",}');
    expect(result.valid).toBe(false);
    expect(result.errors).toBeDefined();
  });

  test("detects unquoted keys", () => {
    const result = validateJson("{name: 'test'}");
    expect(result.valid).toBe(false);
    expect(result.errors).toBeDefined();
  });

  test("detects single quotes instead of double quotes", () => {
    const result = validateJson("{'name': 'test'}");
    expect(result.valid).toBe(false);
    expect(result.errors).toBeDefined();
  });
});

describe("validateJson - schema validation", () => {
  const userSchema: SchemaPattern = {
    type: "object",
    required: ["name", "email"],
    properties: {
      name: { type: "string" },
      email: { type: "string", pattern: /^[^@]+@[^@]+\.[^@]+$/ },
      age: { type: "number", minimum: 0, maximum: 150 },
      active: { type: "boolean" },
    },
  };

  test("validates object matching schema", () => {
    const result = validateJson(
      JSON.stringify({ name: "John", email: "john@example.com", age: 30, active: true }),
      userSchema
    );
    expect(result.valid).toBe(true);
    expect(result.errors).toBeUndefined();
  });

  test("detects missing required property", () => {
    const result = validateJson(JSON.stringify({ name: "John" }), userSchema);
    expect(result.valid).toBe(false);
    expect(result.errors).toBeDefined();
    expect(result.errors?.some((e) => e.message.includes("Required property missing"))).toBe(
      true
    );
  });

  test("detects wrong type for property", () => {
    const result = validateJson(
      JSON.stringify({ name: "John", email: "john@example.com", age: "thirty" }),
      userSchema
    );
    expect(result.valid).toBe(false);
    expect(result.errors).toBeDefined();
    expect(result.errors?.some((e) => e.message.includes("Expected number"))).toBe(true);
  });

  test("detects pattern mismatch for email", () => {
    const result = validateJson(
      JSON.stringify({ name: "John", email: "not-an-email" }),
      userSchema
    );
    expect(result.valid).toBe(false);
    expect(result.errors).toBeDefined();
    expect(result.errors?.some((e) => e.message.includes("does not match required pattern"))).toBe(
      true
    );
  });

  test("validates numeric constraints", () => {
    const result1 = validateJson(
      JSON.stringify({ name: "John", email: "john@example.com", age: -5 }),
      userSchema
    );
    expect(result1.valid).toBe(false);

    const result2 = validateJson(
      JSON.stringify({ name: "John", email: "john@example.com", age: 200 }),
      userSchema
    );
    expect(result2.valid).toBe(false);
  });

  test("validates array schema", () => {
    const arraySchema: SchemaPattern = {
      type: "array",
      items: { type: "number" },
    };

    const validResult = validateJson(JSON.stringify([1, 2, 3, 4, 5]), arraySchema);
    expect(validResult.valid).toBe(true);

    const invalidResult = validateJson(JSON.stringify([1, "two", 3]), arraySchema);
    expect(invalidResult.valid).toBe(false);
  });

  test("validates nested object schema", () => {
    const nestedSchema: SchemaPattern = {
      type: "object",
      properties: {
        user: {
          type: "object",
          required: ["id"],
          properties: {
            id: { type: "number" },
            name: { type: "string" },
          },
        },
      },
    };

    const validResult = validateJson(
      JSON.stringify({ user: { id: 1, name: "John" } }),
      nestedSchema
    );
    expect(validResult.valid).toBe(true);

    const invalidResult = validateJson(JSON.stringify({ user: { name: "John" } }), nestedSchema);
    expect(invalidResult.valid).toBe(false);
    expect(invalidResult.errors?.some((e) => e.path.includes("root.user.id"))).toBe(true);
  });

  test("validates string type", () => {
    const schema: SchemaPattern = { type: "string" };
    expect(validateJson(JSON.stringify("hello"), schema).valid).toBe(true);
    expect(validateJson(JSON.stringify(123), schema).valid).toBe(false);
  });

  test("validates boolean type", () => {
    const schema: SchemaPattern = { type: "boolean" };
    expect(validateJson(JSON.stringify(true), schema).valid).toBe(true);
    expect(validateJson(JSON.stringify(false), schema).valid).toBe(true);
    expect(validateJson(JSON.stringify("true"), schema).valid).toBe(false);
